import os, pty, sys, subprocess, select, time

def run(args, inp=b"", env=None, timeout=20):
    """Run args under a pty. stdin of the child is the pty; write inp then close after delay."""
    m, s = pty.openpty()
    p = subprocess.Popen(args, stdin=s, stdout=s, stderr=s, env=env, close_fds=True)
    os.close(s)
    out = b""
    start = time.time()
    sent = False
    try:
        while True:
            r, _, _ = select.select([m], [], [], 0.2)
            if m in r:
                try:
                    data = os.read(m, 65536)
                except OSError:
                    break
                if not data:
                    break
                out += data
            if not sent and inp:
                time.sleep(0.4)
                try:
                    os.write(m, inp)
                except OSError:
                    pass
                sent = True
            if p.poll() is not None:
                # drain
                while True:
                    r, _, _ = select.select([m], [], [], 0.2)
                    if m not in r:
                        break
                    try:
                        d = os.read(m, 65536)
                    except OSError:
                        break
                    if not d:
                        break
                    out += d
                break
            if time.time() - start > timeout:
                break
    finally:
        try:
            p.terminate()
        except Exception:
            pass
        p.wait()
        os.close(m)
    return p.returncode, out

if __name__ == "__main__":
    rc, out = run(sys.argv[1:], inp=os.environ.get("PTYIN", "").encode())
    sys.stdout.write("RC=%d\n" % rc)
    sys.stdout.buffer.write(out)
    sys.stdout.flush()
