import os, pty, sys, subprocess, select, time

def run(args, lines, timeout=30, delay=0.5):
    m, s = pty.openpty()
    p = subprocess.Popen(args, stdin=s, stdout=s, stderr=s, close_fds=True)
    os.close(s)
    out = b""
    start = time.time()
    idx = 0
    def drain():
        nonlocal out
        while True:
            r, _, _ = select.select([m], [], [], 0.1)
            if m not in r:
                break
            try:
                d = os.read(m, 65536)
            except OSError:
                return
            if not d:
                return
            out += d
    try:
        while True:
            drain()
            if idx < len(lines) and out.count(b"\n") > idx:
                try:
                    os.write(m, lines[idx])
                except OSError:
                    pass
                idx += 1
                drain()
            if p.poll() is not None:
                drain()
                break
            if time.time() - start > timeout:
                break
            time.sleep(0.05)
    finally:
        try: p.terminate()
        except Exception: pass
        p.wait()
        os.close(m)
    return p.returncode, out
