cat > crypto/chacha20poly1305.go <<'EOF'
// Package crypto implements the cryptographic primitives needed by the age
// file format: ChaCha20-Poly1305, HKDF-SHA256, scrypt, SHA-3/Keccak, ML-KEM-768
// and the Bech32 string encoding.
package crypto

import (
	"crypto/hmac"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/binary"
	"errors"
	"math/bits"
)

// ErrBadTag is returned when a ChaCha20-Poly1305 tag fails to authenticate.
var ErrBadTag = errors.New("chacha20poly1305: message authentication failed")

const (
	// KeySize is the size of a ChaCha20-Poly1305 key in bytes.
	KeySize = 32
	// NonceSize is the size of a ChaCha20-Poly1305 nonce in bytes.
	NonceSize = 12
	// Overhead is the size of a ChaCha20-Poly1305 tag in bytes.
	Overhead = 16
	// BlockSize is the size of a ChaCha20 block in bytes.
	BlockSize = 64
)

// chachaQuarterRound performs the ChaCha20 quarter round on four state words.
func chachaQuarterRound(x00, x01, x02, x03 *uint32) {
	x00 += *x01
	*x03 ^= *x00
	*x03 = bits.RotateLeft32(*x03, 16)
	x02 += *x03
	*x01 ^= *x02
	*x01 = bits.RotateLeft32(*x01, 12)
	x00 += *x01
	*x03 ^= *x00
	*x03 = bits.RotateLeft32(*x03, 8)
	x02 += *x03
	*x01 ^= *x02
	*x01 = bits.RotateLeft32(*x01, 7)
}

// chachaBlock computes one ChaCha20 block into dst.
func chachaBlock(dst *[BlockSize]byte, key *[KeySize]byte, nonce *[NonceSize]byte, counter uint32) {
	var state [16]uint32
	state[0] = 0x61707865
	state[1] = 0x3320646e
	state[2] = 0x79622d32
	state[3] = 0x6b206574
	for i := 0; i < 8; i++ {
		state[4+i] = binary.LittleEndian.Uint32(key[4*i:])
	}
	state[12] = counter
	state[13] = binary.LittleEndian.Uint32(nonce[0:])
	state[14] = binary.LittleEndian.Uint32(nonce[4:])
	state[15] = binary.LittleEndian.Uint32(nonce[8:])

	var x [16]uint32
	copy(x[:], state[:])
	for i := 0; i < 10; i++ {
		chachaQuarterRound(&x[0], &x[4], &x[8], &x[12])
		chachaQuarterRound(&x[1], &x[5], &x[9], &x[13])
		chachaQuarterRound(&x[2], &x[6], &x[10], &x[14])
		chachaQuarterRound(&x[3], &x[7], &x[11], &x[15])
		chachaQuarterRound(&x[0], &x[5], &x[10], &x[15])
		chachaQuarterRound(&x[1], &x[6], &x[11], &x[12])
		chachaQuarterRound(&x[2], &x[7], &x[8], &x[13])
		chachaQuarterRound(&x[3], &x[4], &x[9], &x[14])
	}
	for i := range x {
		binary.LittleEndian.PutUint32(dst[4*i:], x[i]+state[i])
	}
}

// chachaXOR encrypts src with the ChaCha20 keystream, starting at counter 0.
func chachaXOR(dst, src []byte, key *[KeySize]byte, nonce *[NonceSize]byte, counter uint32) {
	var block [BlockSize]byte
	for len(src) > 0 {
		chachaBlock(&block, key, nonce, counter)
		n := len(src)
		if n > BlockSize {
			n = BlockSize
		}
		for i := 0; i < n; i++ {
			dst[i] = src[i] ^ block[i]
		}
		dst = dst[n:]
		src = src[n:]
		counter++
	}
}

// poly1305Sum computes the 16 byte Poly1305 tag of msg with key.
func poly1305Sum(msg []byte, key *[32]byte) [16]byte {
	var h [5]uint32
	var r [5]uint32
	r[0] = binary.LittleEndian.Uint32(key[0:]) & 0x3ffffff
	r[1] = (binary.LittleEndian.Uint32(key[3:]) >> 2) & 0x3ffff03
	r[2] = (binary.LittleEndian.Uint32(key[6:]) >> 4) & 0x3ffc0ff
	r[3] = (binary.LittleEndian.Uint32(key[9:]) >> 6) & 0x3f03fff
	r[4] = (binary.LittleEndian.Uint32(key[12:]) >> 8) & 0x00fffff
	r[1] += r[1] >> 24
	r[2] += r[2] >> 26
	r[3] += r[3] >> 26
	r[4] += r[4] >> 26

	var s [4]uint32
	s[0] = binary.LittleEndian.Uint32(key[16:])
	s[1] = binary.LittleEndian.Uint32(key[20:])
	s[2] = binary.LittleEndian.Uint32(key[24:])
	s[3] = binary.LittleEndian.Uint32(key[28:])

	poly1305Blocks(&h, &r, msg, true)

	var out [16]byte
	poly1305Finish(&out, &h, &s)
	return out
}

const (
	maskLow26Bits = 0x3ffffff
	hibit         = 1 << 24
)

func poly1305Blocks(h *[5]uint32, r *[5]uint32, msg []byte, more bool) {
	h0, h1, h2, h3, h4 := h[0], h[1], h[2], h[3], h[4]
	r0, r1, r2, r3, r4 := r[0], r[1], r[2], r[3], r[4]

	for len(msg) >= 64 {
		h0 += binary.LittleEndian.Uint32(msg[0:]) & 0x3ffffff
		h1 += (binary.LittleEndian.Uint32(msg[3:]) >> 2) & 0x3ffffff
		h2 += (binary.LittleEndian.Uint32(msg[6:]) >> 4) & 0x3ffffff
		h3 += (binary.LittleEndian.Uint32(msg[9:]) >> 6) & 0x3ffffff
		h4 += (binary.LittleEndian.Uint32(msg[12:]) >> 8) | hibit

		d0 := uint64(h0)*uint64(r0) + uint64(h1)*uint64(r4)*5 + uint64(h2)*uint64(r3)*5 + uint64(h3)*uint64(r2)*5 + uint64(h4)*uint64(r1)*5
		d1 := uint64(h0)*uint64(r1) + uint64(h1)*uint64(r0) + uint64(h2)*uint64(r4)*5 + uint64(h3)*uint64(r3)*5 + uint64(h4)*uint64(r2)*5
		d2 := uint64(h0)*uint64(r2) + uint64(h1)*uint64(r1) + uint64(h2)*uint64(r0) + uint64(h3)*uint64(r4)*5 + uint64(h4)*uint64(r3)*5
		d3 := uint64(h0)*uint64(r3) + uint64(h1)*uint64(r2) + uint64(h2)*uint64(r1) + uint64(h3)*uint64(r0) + uint64(h4)*uint64(r4)*5
		d4 := uint64(h0)*uint64(r4) + uint64(h1)*uint64(r3) + uint64(h2)*uint64(r2) + uint64(h3)*uint64(r1) + uint64(h4)*uint64(r0)

		cc := d0 >> 26
		h0 = uint32(d0) & 0x3ffffff
		d1 += cc
		cc = d1 >> 26
		h1 = uint32(d1) & 0x3ffffff
		d2 += cc
		cc = d2 >> 26
		h2 = uint32(d2) & 0x3ffffff
		d3 += cc
		cc = d3 >> 26
		h3 = uint32(d3) & 0x3ffffff
		d4 += cc
		cc = d4 >> 26
		h4 = uint32(d4) & 0x3ffffff
		h0 += uint32(cc) * 5
		cc = h0 >> 26
		h0 &= 0x3ffffff
