	h4 &= maskLow26Bits
	h1 += h0 >> 26
	h0 &= maskLow26Bits
	h2 += h1 >> 26
	h1 &= maskLow26Bits
	h3 += h2 >> 26
	h2 &= maskLow26Bits
	h4 += h3 >> 26
