func sliceForAppend(in []byte, n int) (out, tail []byte) {
	if total := len(in) + n; cap(in) >= total {
		out = in[:total]
	} else {
		out = make([]byte, total)
		copy(out, in)
	}
	tail = out[len(in):]
	return
