func HKDF(ikm, salt, info []byte, length int) []byte {
	prk := hkdfExtract(sha256.New, salt, ikm)
	return hkdfExpand(sha256.New, prk, info, length)
}

func hkdfExtract(hash interface {
	BlockSize() int
	Write([]byte) (int, error)
	Sum([]byte) []byte
	Reset()
}, salt, ikm []byte) []byte {
	if salt == nil {
		salt = make([]byte, hash.BlockSize())
	}
	m := hmac.New(sha256.New, salt)
	m.Write(ikm)
	return m.Sum(nil)
}

func hkdfExpand(hash interface {
	BlockSize() int
	Write([]byte) (int, error)
	Sum([]byte) []byte
	Reset()
}, prk, info []byte, length int) []byte {
	var out []byte
	var t []byte
	counter := 1
	for len(out) < length {
		m := hmac.New(sha256.New, prk)
		m.Write(t)
		m.Write(info)
		m.Write([]byte{byte(counter)})
		t = m.Sum(nil)
		out = append(out, t...)
		counter++
	}
	return out[:length]
}
