// chachaQuarterRound performs the ChaCha20 quarter round on four state words.
func chachaQuarterRound(x00, x01, x02, x03 *uint32) {
	x00 += *x01
	*x03 ^= *x00
	*x03 = bits.RotateLeft32(*x03, 16)
	x02 += *x03
	*x01 ^= *x02
	*x01 = bits.RotateLeft32(*x01, 12)
	x00 += *x01
	*x03 ^= *x00
	*x03 = bits.RotateLeft32(*x03, 8)
	x02 += *x03
	*x01 ^= *x02
