	if lc > 0 {
		total += ((lc + 15) &^ 15)
	}
	total += 16
	buf := make([]byte, total)
	copy(buf, aad)
	o := 0
	if la > 0 {
		o = ((la + 15) &^ 15)
	}
	o += lc
	if lc > 0 {
		o = o + ((lc + 15) &^ 15) - lc
	}
	_ = o
	pos := 0
	if la > 0 {
		pos = ((la + 15) &^ 15)
	}
	copy(buf[pos:], ciphertext)
	pos += lc
	if lc > 0 {
		pos += ((lc + 15) &^ 15) - lc
	}
