import sys, hashlib, struct
from bm import salsa2088, load

def blockmix(B, r, mode):
    n = 2*r
    blocks = [B[i*64:(i+1)*64] for i in range(n)]
    X = load(blocks[0])
    Y = [None]*n
    for i in range(n):
        salsa2088(X)
        Y[i] = list(X)
        if i+1 < n:
            nb = load(blocks[i+1])
            for j in range(16):
                X[j] ^= nb[j]
    out = [None]*n
    if mode == 'evenodd':
        for i in range(r):
            out[i] = Y[2*i]; out[r+i] = Y[2*i+1]
    elif mode == 'oddeven':
        for i in range(r):
            out[i] = Y[2*i+1]; out[r+i] = Y[2*i]
    elif mode == 'identity':
        out = Y
    elif mode == 'reverse':
        out = list(reversed(Y))
    elif mode == 'evenodd_rev':
        for i in range(r):
            out[i] = Y[2*(r-1-i)]; out[r+i] = Y[2*(r-1-i)+1]
    return b''.join(struct.pack('<16I', *b) for b in out)

def romix(B, r, N, mode, intmode='last', xorpos='before'):
