func rotl32(x uint32, n uint) uint32 { return bits.RotateLeft32(x, int(n)) }

func salsaQR(x *[16]uint32, a, b, c, d int, r0, r1, r2, r3 uint) {
	x[b] ^= rotl32(x[a]+x[d], r0)
	x[c] ^= rotl32(x[b]+x[a], r1)
	x[d] ^= rotl32(x[c]+x[b], r2)
	x[a] ^= rotl32(x[d]+x[c], r3)
}

func salsaQRX(x *[16]uint32, a, b, c, d int, r0, r1, r2, r3 uint) {
	x[b] = rotl32(x[b]^(x[a]+x[d]), r0)
	x[c] = rotl32(x[c]^(x[b]+x[a]), r1)
	x[d] = rotl32(x[d]^(x[c]+x[b]), r2)
	x[a] = rotl32(x[a]^(x[d]+x[c]), r3)
}

type qrfn func(x *[16]uint32)

var salsaCols = [4][4]int{{0, 4, 8, 12}, {5, 9, 13, 1}, {10, 14, 2, 6}, {15, 3, 11, 7}}
var salsaCols2 = [4][4]int{{0, 4, 8, 12}, {5, 9, 13, 1}, {10, 14, 2, 6}, {15, 3, 7, 11}}
var salsaRows = [4][4]int{{0, 1, 2, 3}, {5, 6, 7, 4}, {10, 11, 8, 9}, {15, 12, 13, 14}}
var salsaRows2 = [4][4]int{{0, 1, 2, 3}, {4, 6, 7, 5}, {10, 11, 8, 9}, {15, 12, 13, 14}}

func mkQR(rot func(*[16]uint32, int, int, int, int, uint, uint, uint, uint), sets [4][4]int, order [4]int, rots [4]uint) qrfn {
	return func(x *[16]uint32) {
		for _, oi := range order {
			s := sets[oi]
			rot(x, s[0], s[1], s[2], s[3], rots[0], rots[1], rots[2], rots[3])
		}
	}
}

func loadWords(b []byte, big bool) [16]uint32 {
	var out [16]uint32
	for i := 0; i < 16; i++ {
		if big {
			out[i] = binary.BigEndian.Uint32(b[4*i:])
		} else {
			out[i] = binary.LittleEndian.Uint32(b[4*i:])
		}
	}
	return out
}

func packWords(w []uint32, out []byte, big bool) {
	for i := 0; i < len(w); i++ {
		if big {
			binary.BigEndian.PutUint32(out[4*i:], w[i])
		} else {
			binary.LittleEndian.PutUint32(out[4*i:], w[i])
		}
	}
}

// blockMix with configurable structure.
// xorsrc: 0=next block, 1=current, 2=previous, 3=none
// outorder: 0=evenodd, 1=identity, 2=oddeven, 3=interleave a, 4=interleave b, 5=x values
func blockMixV(in, out []byte, r int, colQ, rowQ qrfn, nround int, final int, big bool, outorder int, xorsrc int) {
	n := 2 * r
	blocks := make([][]byte, n)
	for i := 0; i < n; i++ {
		blocks[i] = in[i*64 : (i+1)*64]
	}
	x := loadWords(blocks[0], big)
	y := make([]uint32, 16*n)
	for i := 0; i < n; i++ {
		var w [16]uint32
		copy(w[:], x[:])
		for t := 0; t < nround; t++ {
			colQ(&x)
			rowQ(&x)
		}
		switch final {
		case 0:
			for j := 0; j < 16; j++ {
				x[j] += w[j]
			}
		case 1:
			for j := 0; j < 16; j++ {
				x[j] ^= w[j]
			}
		}
		copy(y[i*16:(i+1)*16], x[:])
		var nb [16]uint32
		switch xorsrc {
		case 0:
			if i+1 < n {
				nb = loadWords(blocks[i+1], big)
			}
		case 1:
			nb = loadWords(blocks[i], big)
		case 2:
			if i > 0 {
				nb = loadWords(blocks[i-1], big)
			}
		}
		for j := 0; j < 16; j++ {
			x[j] ^= nb[j]
		}
		if outorder == 5 {
			copy(y[i*16:(i+1)*16], x[:])
		}
	}
	switch outorder {
	case 0:
