		}
	case 4:
		for i := 0; i < r; i++ {
			packWords(y[(r+i)*16:(r+i+1)*16], out[2*i*64:], big)
			packWords(y[i*16:(i+1)*16], out[(2*i+1)*64:], big)
		}
	case 5:
		for i := 0; i < n; i++ {
			packWords(y[i*16:(i+1)*16], out[i*64:], big)
		}
	}
}

func pbkdf2(pw, salt []byte, iter, keyLen int) []byte {
	prf := hmac.New(sha256.New, pw)
	hashLen := prf.Size()
	numBlocks := (keyLen + hashLen - 1) / hashLen
	var buf [4]byte
	dk := make([]byte, 0, numBlocks*hashLen)
	u := make([]byte, hashLen)
	for block := 1; block <= numBlocks; block++ {
		prf.Reset()
		prf.Write(salt)
		buf[0] = byte(block >> 24)
		buf[1] = byte(block >> 16)
		buf[2] = byte(block >> 8)
		buf[3] = byte(block)
		prf.Write(buf[:4])
		dk = prf.Sum(dk)
		t := dk[len(dk)-hashLen:]
		copy(u, t)
		for n := 2; n <= iter; n++ {
			prf.Reset()
			prf.Write(u)
			sum := prf.Sum(nil)
			copy(u, sum)
			for x := range u {
				t[x] ^= u[x]
			}
		}
	}
	return dk[:keyLen]
}

