{"command": "cd /workspace && rm -f probe/brute.go && cat > probe/brute.go <<'EOF'
package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"math/bits"
)

func rotl32(x uint32, n uint) uint32 { return bits.RotateLeft32(x, int(n)) }

func salsaQR(x *[16]uint32, a, b, c, d int, r0, r1, r2, r3 uint) {
	x[b] ^= rotl32(x[a]+x[d], r0)
	x[c] ^= rotl32(x[b]+x[a], r1)
	x[d] ^= rotl32(x[c]+x[b], r2)
	x[a] ^= rotl32(x[d]+x[c], r3)
}

func salsaQRX(x *[16]uint32, a, b, c, d int, r0, r1, r2, r3 uint) {
	x[b] = rotl32(x[b]^(x[a]+x[d]), r0)
	x[c] = rotl32(x[c]^(x[b]+x[a]), r1)
	x[d] = rotl32(x[d]^(x[c]+x[b]), r2)
	x[a] = rotl32(x[a]^(x[d]+x[c]), r3)
}

type qrfn func(x *[16]uint32)

var colSets = [4][4]int{{0, 4, 8, 12}, {5, 9, 13, 1}, {10, 14, 2, 6}, {15, 3, 7, 11}}
var rowSets = [4][4]int{{0, 1, 2, 3}, {5, 6, 7, 4}, {10, 11, 8, 9}, {15, 12, 13, 14}}
var stdRots = [4]uint{7, 9, 13, 18}

func colQ(x *[16]uint32) {
	for _, s := range colSets {
		salsaQR(x, s[0], s[1], s[2], s[3], 7, 9, 13, 18)
	}
}

func rowQ(x *[16]uint32) {
	for _, s := range rowSets {
		salsaQR(x, s[0], s[1], s[2], s[3], 7, 9, 13, 18)
	}
}

func salsa2088(x *[16]uint32) {
	var w [16]uint32
	copy(w[:], x[:])
	for t := 0; t < 2; t++ {
		colQ(x)
		rowQ(x)
	}
	for j := 0; j < 16; j++ {
		x[j] += w[j]
	}
}

func loadW(b []byte) [16]uint32 {
	var out [16]uint32
	for i := 0; i < 16; i++ {
		out[i] = binary.LittleEndian.Uint32(b[4*i:])
	}
	return out
}

func packW(w []uint32, out []byte) {
	for i := 0; i < len(w); i++ {
		binary.LittleEndian.PutUint32(out[4*i:], w[i])
	}
}

// blockMix: xorsrc 0=next, 1=cur, 2=prev, 3=none; outorder 0=evenodd, 1=identity, 2=oddeven, 5=xvalues
func blockMixV(in, out []byte, r int, xorsrc, outorder int) {
	n := 2 * r
	blocks := make([][]byte, n)
	for i := 0; i < n; i++ {
		blocks[i] = in[i*64 : (i+1)*64]
	}
	x := loadW(blocks[0])
	y := make([]uint32, 16*n)
	for i := 0; i < n; i++ {
		salsa2088(&x)
		copy(y[i*16:(i+1)*16], x[:])
		var nb [16]uint32
		switch xorsrc {
		case 0:
			if i+1 < n {
				nb = loadW(blocks[i+1])
			}
		case 1:
			nb = loadW(blocks[i])
		case 2:
			if i > 0 {
				nb = loadW(blocks[i-1])
			}
		}
		for j := 0; j < 16; j++ {
			x[j] ^= nb[j]
		}
		if outorder == 5 {
			copy(y[i*16:(i+1)*16], x[:])
		}
	}
	switch outorder {
	case 0:
		for i := 0; i < r; i++ {
			packW(y[(2*i)*16:(2*i+1)*16], out[i*64:])
			packW(y[(2*i+1)*16:(2*i+2)*16], out[(r+i)*64:])
		}
	case 1:
