func scryptVariant(pw, salt []byte, N, r, p, dkLen int, v variant) []byte {
	b := pbkdf2(pw, salt, 1, p*128*r)
	bs := 128 * r
	for i := 0; i < p; i++ {
		romixVariant(b[i*bs:(i+1)*bs], N, r, v)
	}
	return pbkdf2(pw, b, 1, dkLen)
}

func romixVariant(b []byte, N, r int, v variant) {
	vlen := 128 * r
	vv := make([]byte, vlen*N)
	x := make([]byte, len(b))
	y := make([]byte, len(b))
	copy(x, b)
	for i := 0; i < N; i++ {
		if !v.storeafter {
			copy(vv[i*vlen:], x)
		}
		blockMixVar(x, y, r, v)
		copy(x, y)
		if v.storeafter {
			copy(vv[i*vlen:], x)
		}
	}
	for i := 0; i < N; i++ {
		var j int
		switch v.intmode {
		case 0:
			j = int(binaryLE(x[vlen-64:]) & uint64(N-1))
		case 1:
			j = int(binaryLE(x[0:8]) & uint64(N-1))
		case 2:
			j = int(binaryLE(x[vlen-8:]) & uint64(N-1))
		}
		for k := 0; k < vlen; k++ {
			x[k] ^= vv[j*vlen+k]
		}
		blockMixVar(x, y, r, v)
		copy(x, y)
	}
	copy(b, x)
}

