func parseAgeFile(path string) (salt []byte, logN int, body []byte, args string, err error) {
	d, err := os.ReadFile(path)
	if err != nil {
		return nil, 0, nil, "", err
	}
	lines := splitLines(d)
	// find the stanza
	for _, ln := range lines {
		if len(ln) > 3 && ln[0] == '-' && ln[1] == '>' {
			parts := splitWords(ln[3:])
			typ := parts[0]
			_ = typ
			if len(parts) > 1 {
				args = parts[1]
			}
			if typ == "scrypt" {
				sb, e := base64.RawStdEncoding.DecodeString(parts[1])
				if e != nil {
					return nil, 0, nil, "", e
				}
				salt = sb
				logN = int(parts[2][0] - '0')
				if len(parts[2]) > 1 {
					logN = logN*10 + int(parts[2][1]-'0')
				}
			}
		}
	}
	// body: the line after the stanza
	for i, ln := range lines {
		if len(ln) > 3 && ln[0] == '-' && ln[1] == '>' {
			if i+1 < len(lines) && !(len(lines[i+1]) > 3 && lines[i+1][0] == '-' && lines[i+1][1] == '-' && lines[i+1][2] == '-') {
				b, e := base64.RawStdEncoding.DecodeString(string(lines[i+1]))
				if e != nil {
					return nil, 0, nil, "", e
				}
				body = b
			}
			break
		}
	}
	return salt, logN, body, args, nil
}

func splitLines(d []byte) [][]byte {
	var out [][]byte
	start := 0
	for i := 0; i < len(d); i++ {
		if d[i] == '\n' {
			out = append(out, d[start:i])
			start = i + 1
		}
	}
	if start < len(d) {
		out = append(out, d[start:])
	}
	return out
}

func splitWords(s []byte) []string {
	var out []string
	start := -1
	for i := 0; i <= len(s); i++ {
		if i == len(s) || s[i] == ' ' {
			if start >= 0 {
				out = append(out, string(s[start:i]))
				start = -1
			}
		} else if start < 0 {
			start = i
		}
	}
	return out
}

func oracle() {
	salt, logN, body, args, err := parseAgeFile("/tmp/t/pass.age")
	if err != nil {
		fmt.Println("err", err)
		return
	}
	fmt.Printf("salt=%x logN=%d body=%x args=%q\n", salt, logN, body, args)
	N := 1 << uint(logN)
	pass := []byte("hunter2")
	variants := []variant{}
	for _, outorder := range []int{0, 1, 2, 3, 4, 5} {
		for _, xorsrc := range []int{0, 1, 2, 3} {
			for _, intmode := range []int{0, 1, 2} {
				for _, nround := range []int{1, 2} {
					for _, final := range []int{0, 1, 2} {
						for _, big := range []int{0, 1} {
							for _, xormode := range []int{0, 1} {
								for _, dir := range []int{0, 1} {
									for _, addmode := range []int{0, 1} {
										for _, storeafter := range []bool{false, true} {
											variants = append(variants, variant{outorder, xorsrc, intmode, nround, final, big, xormode, dir, addmode, 0, 0, storeafter, fmt.Sprintf("o%d x%d i%d nr%d f%d b%d xm%d d%d am%d sa%v", outorder, xorsrc, intmode, nround, final, big, xormode, dir, addmode, storeafter)})
										}
									}
								}
							}
						}
					}
				}
			}
		}
	}
	fmt.Println("variants:", len(variants))
	// parallel
	sem := make(chan struct{}, runtime.NumCPU()/2)
	var mu sync.Mutex
	found := 0
	done := 0
	var wg sync.WaitGroup
	for _, v := range variants {
		wg.Add(1)
		go func(v variant) {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()
			k := scryptVariant(pass, salt, N, 8, 1, 32, v)
			// try to decrypt the body
			for _, aad := range [][]byte{nil, []byte(args)} {
				plain, e := cryptoOpen(k, body, aad)
				if e == nil {
					mu.Lock()
					fmt.Printf("MATCH variant=%s aad=%q plaintext=%x\n", v.name, aad, plain)
					found++
					mu.Unlock()
				}
			}
			mu.Lock()
			done++
			if done%1000 == 0 {
				fmt.Printf("  %d/%d done, found=%d\n", done, len(variants), found)
			}
			mu.Unlock()
		}(v)
	}
	wg.Wait()
	fmt.Println("total found:", found)
}
