// cryptoOpen is a helper for the probe: ChaCha20-Poly1305 open with a zero nonce.
func cryptoOpen(key, ciphertext, aad []byte) ([]byte, error) {
	c, err := crypto.NewChaCha20Poly1305(key)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, 12)
	return c.Open(nil, nonce, ciphertext, aad)
}
