	lines := splitLines(d)
	var stanza, bodyLine, macLine string
	var payload []byte
	for i, ln := range lines {
		s := string(ln)
		if len(s) > 3 && s[0] == '-' && s[1] == '>' && stanza == "" {
			stanza = s
			if i+1 < len(lines) {
				bodyLine = string(lines[i+1])
			}
			if i+2 < len(lines) {
				macLine = string(lines[i+2])
			}
			payload = d[i+3:]
			break
		}
	}
	fmt.Println("stanza:", stanza)
	fmt.Println("body:", bodyLine)
	fmt.Println("mac:", macLine, "payload len:", len(payload))
	words := splitWords([]byte(stanza[3:]))
	fmt.Println("args:", words)
	eph, e1 := base64.RawStdEncoding.DecodeString(words[2])
	if e1 != nil {
		fmt.Println("eph decode err", e1)
	}
	body, e2 := base64.RawStdEncoding.DecodeString(bodyLine)
	if e2 != nil {
		fmt.Println("body decode err", e2)
	}
	fmt.Println("eph:", hexs(eph), "body:", hexs(body))

	// ssh pubkey blob
	pubLine := readFile("/tmp/t/ed25519.key.pub")
	blob := unhexOrB64(pubLine[1])
	fmt.Println("pub blob:", hexs(blob), "len", len(blob))

	shared, err := priv.ECDH(mustPub(curve, eph))
	if err != nil {
		fmt.Println("ecdh err", err)
		return
	}
	fmt.Println("shared:", hexs(shared))

	// candidate salts
	cand := map[string][]byte{}
	cand["sha(eph||pub)"] = sha256Sum2(append(append([]byte{}, eph...), blob...))
	cand["sha(pub||eph)"] = sha256Sum2(append(append([]byte{}, blob...), eph...))
	cand["eph||pub"] = append(append([]byte{}, eph...), blob...)
	cand["pub||eph"] = append(append([]byte{}, blob...), eph...)
	cand["nil"] = nil
	infos := []string{"age-encryption.org/v1/ssh-ed25519", "ssh-ed25519", "", "age-encryption.org/v1", "ssh-ed25519\x00", "age-encryption.org/v1/ssh-ed25519\x00"}
	aads := [][]byte{nil, []byte(words[1]), eph, blob, []byte(stanza)}
	nonces := [][]byte{make([]byte, 12)}
	found := 0
	for sn, sv := range cand {
		for _, info := range infos {
			k := crypto.HKDF(shared, sv, []byte(info), 32)
			for _, aad := range aads {
				fk, err := cryptoOpen(k, body, aad)
				if err != nil {
					continue
				}
				fmt.Printf("STANZA OPEN OK salt=%s info=%q aad=%q filekey=%s\n", sn, info, aad, hexs(fk))
				// try to decrypt the payload
				for pn, pv := range payloadNonces(payload, fk) {
					for _, paad := range aads {
						pt, err := cryptoOpen(fk, pv, payload[16:], paad)
						if err == nil {
							fmt.Printf("  PAYLOAD OK nonce=%d aad=%q plaintext=%q\n", pn, paad, pt)
							found++
						}
					}
				}
			}
		}
	}
	fmt.Println("found:", found)
}

func payloadNonces(payload, fk []byte) map[int][]byte {
	out := map[int][]byte{}
	if len(payload) < 28 {
		return out
	}
	x := payload[:16]
	out[0] = make([]byte, 12)
	out[1] = x[:12]
	out[2] = x[4:16]
	out[3] = crypto.HKDF(fk, nil, []byte("age-encryption.org/v1/payload"), 12)
	out[4] = crypto.HKDF(fk, x, nil, 12)
	return out
}

func hexs(b []byte) string {
	r := ""
	for _, c := range b {
		r += fmt.Sprintf("%02x", c)
	}
	return r
}

func sha256Sum2(b []byte) []byte {
	h := sha256.Sum256(b)
	return h[:]
}

func mustPub(curve *ecdh.Curve, b []byte) *ecdh.PublicKey {
	p, err := curve.NewPublicKey(b)
	if err != nil {
		panic(err)
	}
	return p
}

func readFile(path string) []string {
	d, _ := os.ReadFile(path)
	return splitLines(d)
}

func unhexOrB64(s string) []byte {
	if b, err := base64.StdEncoding.DecodeString(s); err == nil && len(b) > 0 {
		return b
	}
	return unhex(s)
}
