				fk, err := cryptoOpen(k, body, aad)
				if err != nil {
					continue
				}
				fmt.Printf("STANZA OPEN OK salt=%s info=%q aad=%q filekey=%s\n", sn, info, aad, hexs(fk))
				// try to decrypt the payload
				for pn, pv := range payloadNonces(payload, fk) {
					for _, paad := range aads {
						pt, err := cryptoOpen(fk, pv, payload[16:], paad)
						if err == nil {
