func payloadNonces(payload, fk []byte) map[int][]byte {
	out := map[int][]byte{}
	if len(payload) < 28 {
		return out
	}
	x := payload[:16]
	out[0] = make([]byte, 12)
	out[1] = x[:12]
	out[2] = x[4:16]
