	}
	return r
}

func sha256Sum2(b []byte) []byte {
	h := sha256.Sum256(b)
	return h[:]
}

func mustPub(curve *ecdh.Curve, b []byte) *ecdh.PublicKey {
	p, err := curve.NewPublicKey(b)
	if err != nil {
		panic(err)
	}
	return p
}

func readFile(path string) []string {
	d, _ := os.ReadFile(path)
	return splitLines(d)
}

func unhexOrB64(s string) []byte {
	if b, err := base64.StdEncoding.DecodeString(s); err == nil && len(b) > 0 {
		return b
	}
	return unhex(s)
}
