// macCandidates computes candidate header MACs for a file key.
func macCandidates(fk []byte, header []byte) map[string][]byte {
	out := map[string][]byte{}
	for _, info := range []string{"age-encryption.org/v1/header", "header", "", "age-encryption.org/v1",
		"age-encryption.org/v1/header\x00", "age/age-encryption.org/v1/header"} {
		for _, klen := range []int{32, 16} {
			k := crypto.HKDF(fk, nil, []byte(info), klen)
			m := hmac.New(sha256.New, k)
			m.Write(header)
			out[fmt.Sprintf("info=%q len=%d", info, klen)] = m.Sum(nil)
		}
	}
	return out
}

