			stanza = str
			bodyLine = string(lines[i+1])
			macLine = string(lines[i+2])
			// header up to and including "--- "
			headerUpToMac = d[:off+len(ln)+1+len(lines[i+1])+1+4]
			po := off + len(ln) + 1 + len(lines[i+1]) + 1 + len(lines[i+2]) + 1
			payload = d[po:]
			break
		}
	}
