	eph, _ := base64.RawStdEncoding.DecodeString(words[2])
	body, _ := base64.RawStdEncoding.DecodeString(bodyLine)
	macVal, _ := base64.RawStdEncoding.DecodeString(string(macLine[4:]))
	pubFile, _ := os.ReadFile("/tmp/t/ed25519.key.pub")
