	if err != nil {
		fmt.Println("ecdh err", err)
		return
	}
	xPub := priv.PublicKey().Bytes()
	salts := map[string][]byte{
		"sha(eph||xpub)": sha256Sum2(append(append([]byte{}, eph...), xPub...)),
		"sha(xpub||eph)": sha256Sum2(append(append([]byte{}, xPub...), eph...)),
		"eph||xpub":      append(append([]byte{}, eph...), xPub...),
		"xpub||eph":      append(append([]byte{}, xPub...), eph...),
		"nil":            nil,
		"sha(eph||blob)": sha256Sum2(append(append([]byte{}, eph...), blob...)),
		"eph||blob":      append(append([]byte{}, eph...), blob...),
	}
