		"blob||eph":      append(append([]byte{}, blob...), eph...),
	}
	infos := []string{"age-encryption.org/v1/ssh-ed25519", "ssh-ed25519", "", "age-encryption.org/v1",
		"age-encryption.org/v1/ssh-ed25519/wrap", "ssh-ed25519/wrap", "age-encryption.org/v1/X25519",
		"wrap", "file key", "header"}
