								found++
							} else {
								fmt.Printf("aead-ok-but-mac-fail mks=%v salt=%s info=%q nonce=%d aad=%q fk=%s\n", mks, sn, info, nonce[0], aad, hexs(fk))
							}
						}
					}
				}
			}
		}
	}
	fmt.Println("found:", found)
}

func macOK(fk, hdr, want []byte) bool {
	k := crypto.HKDF(fk, nil, []byte("header"), 32)
	m := hmacSHA256(k, hdr)
	return hexs(m) == hexs(want)
}

func hmacSHA256(k, m []byte) []byte {
	// use crypto's hmac? use stdlib
	return hmacStdlib(k, m)
}

func indexOf(d, sub []byte) int {
	for i := 0; i+len(sub) <= len(d); i++ {
		ok := true
		for j := range sub {
			if d[i+j] != sub[j] {
				ok = false
				break
			}
		}
		if ok {
			return i
		}
	}
	return -1
}
