}

func hmacSHA256(k, m []byte) []byte {
	// use crypto's hmac? use stdlib
	return hmacStdlib(k, m)
}

func indexOf(d, sub []byte) int {
	for i := 0; i+len(sub) <= len(d); i++ {
		ok := true
		for j := range sub {
			if d[i+j] != sub[j] {
				ok = false
				break
			}
		}
		if ok {
			return i
		}
	}
	return -1
}
